.omsTextPresetLibrary{border:1px solid var(--line,#364056);border-radius:10px;background:var(--panel2,#20283b);margin:4px 0 10px;padding:10px;min-width:0}
.omsTextPresetLibrary summary{font-size:12px;font-weight:700;color:var(--text,#e5ecf4);cursor:pointer;min-height:28px;line-height:28px}
.omsTextPresetFilters{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
.omsTextPresetFilters input,.omsTextPresetFilters select{flex:1 1 140px;min-width:0;width:100%;max-width:100%;min-height:36px;border:1px solid var(--line,#364056);border-radius:8px;background:var(--panel,#141a29);color:var(--text,#e5ecf4);padding:7px 9px;font:inherit;font-size:12px;box-sizing:border-box}
.omsTextPresetLibrary output{display:block;font-size:11px;color:var(--muted,#a1afc5);margin:5px 0}
.omsTextPresetGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;max-height:250px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;padding:1px;min-width:0}
.omsTextPresetGrid button{display:flex;flex-direction:column;gap:4px;text-align:left;padding:10px;min-height:68px;min-width:0;border:1px solid var(--line,#364056);border-radius:9px;background:var(--panel,#141a29);color:var(--text,#e5ecf4);cursor:pointer;font:inherit;white-space:normal;overflow-wrap:anywhere}
.omsTextPresetGrid button strong{font-size:12px;line-height:1.35}.omsTextPresetGrid button small{font-size:10px;color:var(--accent,#56cfbf)}.omsTextPresetGrid button span{font-size:10px;line-height:1.4;color:var(--muted,#a1afc5)}
.omsTextPresetGrid button:hover{border-color:var(--accent,#56cfbf)}.omsTextPresetGrid button:focus-visible,.omsTextPresetFilters :focus-visible{outline:2px solid var(--accent,#56cfbf);outline-offset:1px}.omsTextPresetGrid button:disabled{opacity:.45;cursor:not-allowed}
.omsTextPresetGrid [hidden],.omsTextPresetEmpty[hidden]{display:none!important}
.omsTextPresetLibrary .miniNote{font-size:10px;line-height:1.5;margin:8px 0 0}
@media(min-width:900px){.omsTextPresetGrid{grid-template-columns:repeat(3,minmax(0,1fr));max-height:280px}}
.omsTextCustomPresets{margin-top:10px;border-top:1px solid var(--line,#364056);padding-top:6px;min-width:0}
.omsTextPresetFilters button,.omsTextClockButton{min-height:36px;max-width:100%;border:1px solid var(--line,#364056);border-radius:8px;background:var(--panel,#141a29);color:var(--text,#e5ecf4);padding:7px 10px;font:inherit;font-size:12px;white-space:normal;overflow-wrap:anywhere;cursor:pointer}
.omsTextPresetFilters button{flex:1 1 120px;min-width:0}.omsTextClockButton{width:100%;margin-bottom:8px}
.omsTextPresetFilters button:disabled,.omsTextClockButton:disabled{opacity:.45;cursor:not-allowed}
.omsTextPresetLibrary input[hidden]{display:none!important}
.omsTextExpression{min-width:0;margin:8px 0;padding:8px;border:1px solid var(--line,#364056);border-radius:8px;background:var(--panel2,#20283b)}
.omsTextExpression summary{cursor:pointer;font-size:12px;line-height:28px;color:var(--text,#e5ecf4)}
.omsTextExpression textarea{display:block;box-sizing:border-box;width:100%;max-width:100%;height:100px;margin:8px 0;background:var(--panel,#141a29);color:var(--text,#e5ecf4);border:1px solid var(--line,#364056);border-radius:8px;padding:8px;font:12px/1.5 monospace;resize:vertical}
.omsTextExpression button{min-height:36px;padding:7px 12px;border:1px solid var(--line,#364056);border-radius:8px;background:var(--panel,#141a29);color:var(--text,#e5ecf4);cursor:pointer}
.omsTextExpression output{display:block;color:var(--muted,#a1afc5);font-size:11px;overflow-wrap:anywhere;margin-top:6px}
#drawer .effectParams,#drawer .omsTextPresetLibrary{overflow-anchor:none}
.omsTextPackageMode{display:block;margin-top:8px;font-size:11px;color:var(--muted,#a1afc5);min-width:0}
.omsTextPackageMode select{display:block;box-sizing:border-box;width:100%;max-width:100%;min-height:36px;margin-top:5px;border:1px solid var(--line,#364056);border-radius:8px;background:var(--panel,#141a29);color:var(--text,#e5ecf4);padding:7px 9px;font:inherit}

.omsExprEditor{padding:12px 14px;display:grid;gap:10px;min-width:0;border-bottom:1px solid #70819a26}
.omsExprName,.omsExprTarget,.omsExprCodeLabel{display:grid;gap:6px;font-size:12px;color:var(--muted,#a5b0c5)}
.omsExprEditor input,.omsExprEditor select,.omsExprEditor textarea{box-sizing:border-box;width:100%;min-width:0;border:1px solid #70819a50;border-radius:8px;background:var(--panel,#1c2230);color:var(--text,#e8edf7);padding:9px;font:inherit}
.omsExprEditor textarea{font-family:ui-monospace,Consolas,monospace;font-size:13px;min-height:116px;resize:vertical;line-height:1.6;tab-size:2}
.omsExprEditor textarea:focus,.omsExprEditor input:focus,.omsExprEditor select:focus{outline:1px solid var(--accent,#53cbb6)}
.omsExprActions{display:flex;flex-wrap:wrap;gap:6px}
.omsExprActions button{font:inherit;font-size:12px;border:1px solid #53cbb650;border-radius:8px;background:#53cbb619;color:var(--text,#e8edf7);padding:9px 12px;cursor:pointer;min-height:38px}
.omsExprActions button:first-child{background:#53cbb638}
.omsExprStatus{display:block;font-size:11px;line-height:1.5;color:var(--accent,#53cbb6);overflow-wrap:anywhere}
.omsExprStatus.error{color:#ed899a}
.omsExprHelp{font-size:11px;line-height:1.7;min-width:0}.omsExprHelp summary{cursor:pointer;color:var(--muted,#a5b0c5)}
.omsExprHelp p{margin:8px 0}.omsExprHelp pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0;border:1px solid #70819a30;padding:8px;border-radius:8px;color:var(--text,#e8edf7)}
